a <- grep('^--file=',commandArgs(FALSE),value=TRUE)
if (!length(a)) stop('Run with Rscript')
folder <- dirname(normalizePath(sub('^--file=','',a[1])))
item_name <- tools::file_path_sans_ext(basename(sub('^--file=','',a[1])))
root <- dirname(folder)
s <- utils::read.csv(file.path(folder,paste0(item_name,'_snapshot.csv')),check.names=FALSE,colClasses='character',na.strings='',fileEncoding='UTF-8')
num <- function(x) as.numeric(gsub(',','',x,fixed=TRUE))
final.dataframe <- data.frame(source_order=seq_len(nrow(s)),lamina=s$Lamina,source_species='Macaca fascicularis; Macaca mulatta',Species=NA_character_,neurons_per_mm3=num(s[['A neurons per mm³ (thousands)']])*1e3,neurons_per_mm3_SD=num(s[['A SD']])*1e3,neurons_under_1mm2=num(s[['B neurons under 1 mm² (thousands)']])*1e3,neurons_under_1mm2_SD=num(s[['B SD']])*1e3,neurons_under_25x25um=num(s[['C neurons under 25×25 µm']]),neurons_under_25x25um_SD=num(s[['C SD']]),area17_hemisphere_neurons=num(s[['D neurons in one hemisphere (millions)']])*1e6,area17_hemisphere_neurons_SD=num(s[['D SD']])*1e6,stringsAsFactors=FALSE)
stopifnot(nrow(final.dataframe)==14L,sum(final.dataframe$area17_hemisphere_neurons[1:13])==final.dataframe$area17_hemisphere_neurons[14],abs(sum(final.dataframe$neurons_under_1mm2[1:13])-final.dataframe$neurons_under_1mm2[14])<=100)
utils::write.csv(final.dataframe,file.path(folder,paste0(item_name,'.csv')),row.names=FALSE,na='',fileEncoding='UTF-8')
reg <- readxl::read_excel(file.path(root,'__ReadMeAddON.xlsx'),sheet='Sheet1')
hit <- which(reg[['Item name']]==item_name)
if(length(hit)!=1L) stop('Expected one AddON registry row')
encoded <- as.character(reg[['Item encoded']][hit])
utils::write.table(final.dataframe,file.path(root,'__Public','comparative-data',paste0(encoded,'.tsv')),sep='	',row.names=FALSE,na='',fileEncoding='UTF-8')
cat(item_name,': ',nrow(final.dataframe),' rows
',sep='')
